<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {frontendDocument} from '../code/frontend.js';import {codeHash} from '../code/workspace.js';
const props=defineProps({node:Object,rows:Array,theme:Object,playing:Boolean,interactive:Boolean});const emit=defineEmits(['action']);const host=ref(),frames=ref([]),active=ref(''),state=ref('idle'),error=ref(''),currentHash=ref(''),currentActivation=ref(''),requested=ref('');let observer,timer;const workspace=computed(()=>props.node.props.codeWorkspace),signature=computed(()=>workspace.value?.enabled!==false&&workspace.value?.activeFiles?.length?codeHash(workspace.value.activeFiles)+'|'+(workspace.value.activeEntry||workspace.value.entry)+'|'+(workspace.value.activation||''):'');
function send(target){const rect=host.value?.getBoundingClientRect();for(const frame of host.value?.querySelectorAll('iframe')||[]){if(target&&target!==frame.contentWindow)continue;const entry=frames.value.find(f=>f.token===frame.dataset.codeToken);frame.contentWindow?.postMessage({token:frame.dataset.codeToken,rows:JSON.parse(JSON.stringify(props.rows||[])),theme:JSON.parse(JSON.stringify(props.theme||{})),parameters:JSON.parse(JSON.stringify(entry?.parameters||{})),playing:props.playing&&!document.hidden&&!entry?.failed,size:{width:rect?.width||props.node.w,height:rect?.height||props.node.h}},'*');}}
function receive(e){const frame=[...(host.value?.querySelectorAll('iframe')||[])].find(f=>f.contentWindow===e.source);if(!frame||e.data?.token!==frame.dataset.codeToken||!e.data.astraCode)return;const {type,value,token}=e.data;if(type==='boot')send(e.source);if(type==='ready'){if(token!==requested.value)return;active.value=token;frames.value=frames.value.filter(f=>f.token===token);state.value='ready';error.value='';clearTimeout(timer);}if(type==='error'){const entry=frames.value.find(f=>f.token===token);if(entry)entry.failed=true;if(token!==requested.value)return;state.value='error';error.value=value.message+(value.stack?'\n'+value.stack:'');if(token!==active.value)frames.value=frames.value.filter(f=>f.token!==token);clearTimeout(timer);}if(type==='action'&&token===active.value&&props.interactive)emit('action',value.name,value.value||{});}
watch(signature,()=>{clearTimeout(timer);error.value='';if(!signature.value){state.value='idle';frames.value=[];active.value='';currentHash.value='';currentActivation.value='';requested.value='';return;}state.value='building';currentHash.value=signature.value.split('|')[0];const token=crypto.randomUUID();requested.value=token;currentActivation.value=workspace.value?.activation||'';try{const source=frontendDocument(workspace.value,token);frames.value=[...frames.value.filter(f=>f.token===active.value),{token,source,activation:workspace.value?.activation,parameters:JSON.parse(JSON.stringify(workspace.value?.activeParameters||workspace.value?.parameters||{}))}];timer=setTimeout(()=>{state.value='error';error.value='前端组件启动超时，请检查入口与资源预算';frames.value=frames.value.filter(f=>f.token===active.value);},8000);}catch(e){state.value='error';error.value=e.message;}},{immediate:true});watch(()=>[props.rows,props.theme,props.playing,workspace.value?.activeParameters],()=>send(),{deep:true});watch(host,el=>{observer?.disconnect();if(el){observer=new ResizeObserver(()=>send());observer.observe(el);}});window.addEventListener('message',receive);const visibility=()=>send();document.addEventListener('visibilitychange',visibility);onBeforeUnmount(()=>{clearTimeout(timer);observer?.disconnect();window.removeEventListener('message',receive);document.removeEventListener('visibilitychange',visibility);});
</script>
<template><div ref="host" class="aw-frontend-code" :data-code-state="state" :data-code-hash="currentHash" :data-code-activation="currentActivation" :data-code-error="error"><iframe v-for="f in frames" :key="f.token" :data-code-token="f.token" :srcdoc="f.source" sandbox="allow-scripts" title="自定义前端组件" referrerpolicy="no-referrer" :style="{pointerEvents:interactive&&active===f.token?'auto':'none',visibility:active===f.token?'visible':'hidden'}" @load="send($event.target.contentWindow)"></iframe><div v-if="state==='idle'" class="aw-code-placeholder"><span>⟨/⟩</span><strong>自由编写，让想法不受组件限制</strong><small>打开代码工作区，或让智能体为你创建</small></div><div v-if="state==='error'" class="aw-code-error" role="alert">{{error.split('\n')[0]}}</div></div></template>
<style>.aw-frontend-code{position:relative;width:100%;height:100%;min-height:40px}.aw-frontend-code iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:transparent}.aw-code-placeholder{height:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px;font-size:12px;color:var(--aw-muted)}.aw-code-placeholder>span{font:28px monospace;color:var(--aw-accent)}.aw-code-placeholder strong{font-weight:400}.aw-code-placeholder small{font-size:10px;opacity:.6}.aw-code-error{position:absolute;left:8px;right:8px;bottom:8px;padding:9px 12px;border:1px solid #e6b99555;border-radius:5px;background:#2b2020ed;color:#dbbba1;font:10px/1.6 monospace;max-height:90px;overflow:auto}</style>
